using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with a default resolver (handles common types automatically)
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
JsonTypeInfo<WeatherForecast> typedInfo = options.GetTypeInfo<WeatherForecast>();
Console.WriteLine($"GetTypeInfo<WeatherForecast> returned type: {typedInfo.Type.Name}");

var forecast = new WeatherForecast("Seattle", 18.5);
string json = JsonSerializer.Serialize(forecast, typedInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): check-without-throwing ---
// With the default resolver this will succeed for a known type:
if (options.TryGetTypeInfo<WeatherForecast>(out JsonTypeInfo<WeatherForecast>? info))
{
    Console.WriteLine($"TryGetTypeInfo succeeded for {info!.Type.Name}");
}

// Now use a source-generated context that only knows about WeatherForecast.
// Querying for an unregistered type (int[]) returns false instead of throwing.
var restricted = new JsonSerializerOptions { TypeInfoResolver = MyContext.Default };

if (restricted.TryGetTypeInfo<int[]>(out JsonTypeInfo<int[]>? arrayInfo))
{
    Console.WriteLine($"Resolved int[] info: {arrayInfo!.Type.Name}");
}
else
{
    Console.WriteLine("TryGetTypeInfo<int[]> returned false — no metadata available (no exception thrown)");
}

// Types ---
public record WeatherForecast(string City, double TempC);

[JsonSerializable(typeof(WeatherForecast))]
public partial class MyContext : JsonSerializerContext;

